      </el-collapse-item></el-collapse>
    </template>
    <el-dialog v-model="detailOpen" title="成人AKI原评估来源复核" width="min(1150px,96vw)"><ai-aki-findings v-if="allowed && selected" :source="selected.specialist_source" :scope="selected" :expected-patient-id="patientId" :expected-admission-id="admissionId" @inspect="$emit('inspect', $event)" /></el-dialog>
  </section>
</template>
<script setup>
