const emit = defineEmits(["selection", "availability", "inspect"]), store = useStore();
const roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => props.active && !!store.state.user.accessToken && Number.isSafeInteger(props.patientId) && props.patientId > 0 && !!props.admissionId && !!props.windowId && roles.value.some(role => ["nurse", "doctor", "director", "admin", "super_admin"].includes(role)));
const blank = () => ({ profileId: "", evaluation_at: "", age: "", age_basis_note: "", indexId: "", comparisonId: "", baselineId: "", baseline_mode: "", serum_creatinine_confirmed: false, creatinine_review_note: "", baseline_rise_within_7d_confirmed: false, baseline_review_note: "", weightId: "", weight_applicability_confirmed: false, weight_basis_note: "", urineIds: [], rrt_status: "", rrt_started_at: "", rrt_acute_aki_confirmed: false, rrt_basis_note: "" });
const form = ref(blank()), sources = ref([]), page = ref(1), total = ref(null), selectedId = ref(""), selected = ref(null), detailOpen = ref(false), revokeReason = ref(""), error = ref(""), notice = ref(""), loading = ref(false), checking = ref(false), creating = ref(false), revoking = ref(false), candidateLoading = ref(false), baselineLoading = ref(false);
const creatinines = ref([]), baselines = ref([]), weights = ref([]), urine = ref([]), profiles = ref([]), baselineAdmissions = ref([]), baselineAdmission = ref(""), baselinePage = ref(1), baselineTotal = ref(null), candidatesWindowHash = ref(""), canSignResponse = ref(false);
let epoch = 0, listSequence = 0, detailSequence = 0, candidateSequence = 0, baselineSequence = 0, inactive = false;
