const chosenCreatinines = computed(() => [["index", creatinines.value.find(row => row.lab_source_id === form.value.indexId)], ["48小时比较", creatinines.value.find(row => row.lab_source_id === form.value.comparisonId)], ["基线", baselines.value.find(row => row.lab_source_id === form.value.baselineId)]].filter(([, row]) => row).map(([label, item]) => ({ label, item })));
function clearSelection() { detailSequence++; selectedId.value = ""; selected.value = null; checking.value = false; detailOpen.value = false; revokeReason.value = ""; emit("selection", null); emit("availability", false); }
function reset() { epoch++; listSequence++; candidateSequence++; baselineSequence++; clearSelection(); form.value = blank(); sources.value = []; creatinines.value = []; baselines.value = []; weights.value = []; urine.value = []; profiles.value = []; baselineAdmissions.value = []; baselineAdmission.value = ""; baselinePage.value = page.value = 1; baselineTotal.value = total.value = null; candidatesWindowHash.value = ""; canSignResponse.value = false; loading.value = checking.value = candidateLoading.value = baselineLoading.value = creating.value = revoking.value = false; error.value = notice.value = ""; }
