  const weight = draft.weightId ? weights.value.find(row => row.observation_id === draft.weightId) : null;
  if (draft.weightId && !weight) throw new Error("原体重已不在当前核对目录");
  if (draft.weight_applicability_confirmed && (!weight || draft.weight_basis_note.trim().length < 20)) throw new Error("整段体重适用声明须有实际原体重点和至少20字依据");
  const intervals = draft.urineIds.map(id => { const row = urine.value.find(item => item.interval_id === id); if (!row) throw new Error("原尿量区间已不在当前核对目录"); return { interval_id: id, expected_content_hash: row.content_hash }; });
