  if (clinicalRrt && (!canSign.value || draft.rrt_basis_note.trim().length < 20 || (acute && (!draft.rrt_acute_aki_confirmed || !draft.rrt_started_at)))) throw new Error("RRT事实须有实际临床资格、明确原依据；新急性启动另须原启动UTC与AKI用途确认");
  return { ...query(ticket), expected_window_hash: candidatesWindowHash.value, rule_profile_id: draft.profileId, expected_rule_profile_hash: profiles.value.find(row => row.rule_profile_id === draft.profileId).content_hash, evaluation_at: evaluation, age_at_evaluation_years: Number(draft.age), age_basis_note: draft.age_basis_note.trim(), index_creatinine: index, comparison_48h: comparison, baseline_creatinine: baseline, baseline_mode: draft.baseline_mode, serum_creatinine_confirmed: anyLab && draft.serum_creatinine_confirmed, creatinine_review_note: anyLab ? draft.creatinine_review_note.trim() : null, baseline_rise_within_7d_confirmed: draft.baseline_mode === "presumed_within_7d" ? draft.baseline_rise_within_7d_confirmed : null, baseline_review_note: draft.baseline_mode === "presumed_within_7d" ? draft.baseline_review_note.trim() : null, weight_point: weight ? { observation_id: weight.observation_id, expected_content_hash: weight.content_hash } : null, weight_applicability_confirmed: draft.weight_applicability_confirmed, weight_basis_note: draft.weight_applicability_confirmed ? draft.weight_basis_note.trim() : null, urine_intervals: intervals, rrt_status: draft.rrt_status, rrt_started_at: clinicalRrt && draft.rrt_status !== "not_initiated" && draft.rrt_started_at ? explicitUtc(draft.rrt_started_at) : null, rrt_acute_aki_confirmed: acute ? draft.rrt_acute_aki_confirmed : null, rrt_basis_note: clinicalRrt ? draft.rrt_basis_note.trim() : null };
}
const formError = computed(() => { try { payload(); return ""; } catch (failure) { return failure.message; } }), canCreate = computed(() => allowed.value && !inactive && !creating.value && !candidateLoading.value && !baselineLoading.value && !formError.value);
async function loadSources() { clearSelection(); if (!allowed.value || inactive) return; const ticket = capture(), seq = ++listSequence; loading.value = true; sources.value = []; error.value = ""; try { const res = await getAkiAssessments({ ...query(ticket), page: page.value, page_size: 50 }); if (!current(ticket) || seq !== listSequence) return; if (!Array.isArray(res.data?.items) || res.data.items.some(row => !akiAssessmentMatches(row, ticket.patientId, ticket.admissionId, ticket.windowId))) throw new Error("成人AKI目录与原患者、住院或窗口不一致"); sources.value = res.data.items; total.value = res.data.total; } catch (failure) { if (current(ticket) && seq === listSequence) error.value = failure?.message || "成人AKI目录未能读取"; } finally { if (current(ticket) && seq === listSequence) loading.value = false; } }
