  if (window?.patient_id !== ticket.patientId || window.admission_id !== ticket.admissionId || window.window_id !== ticket.windowId || !/^[a-f0-9]{64}$/.test(window.content_hash || "") || !Array.isArray(data.creatinine_sources) || data.creatinine_sources.some(row => !row.snapshot || !labSourceMatches(row, ticket.patientId, ticket.admissionId)) || !Array.isArray(data.baseline_sources) || data.baseline_sources.some(row => !row.snapshot || !labSourceMatches(row, ticket.patientId, originalAdmission)) || !Array.isArray(data.baseline_admissions) || !Array.isArray(data.weight_points) || data.weight_points.some(row => row.patient_id !== ticket.patientId || row.admission_id !== ticket.admissionId || !row.payload?.measurements?.body_weight) || !Array.isArray(data.urine_intervals) || data.urine_intervals.some(row => row.patient_id !== ticket.patientId || row.admission_id !== ticket.admissionId || !row.payload) || !Array.isArray(data.rule_profiles)) throw new Error("AKI原来源、原住院或规则回执不一致");
}
async function loadCandidates() { if (!allowed.value || inactive || creating.value) return; baselineSequence++; baselineLoading.value = false; form.value = blank(); baselineAdmission.value = ""; baselinePage.value = 1; creatinines.value = []; baselines.value = []; weights.value = []; urine.value = []; profiles.value = []; canSignResponse.value = false; const ticket = capture(), seq = ++candidateSequence; candidateLoading.value = true; error.value = ""; try { const res = await getAkiCandidates(query(ticket)); if (!current(ticket) || seq !== candidateSequence) return; const data = res.data; validateCandidates(data, ticket, ticket.admissionId); creatinines.value = data.creatinine_sources; baselines.value = data.baseline_sources; weights.value = data.weight_points; urine.value = data.urine_intervals; baselineAdmissions.value = data.baseline_admissions; baselineTotal.value = data.baseline_total; profiles.value = data.rule_profiles.filter(row => row.rule_id === "kdigo_aki_2012" && row.status === "published" && row.revision === 2); candidatesWindowHash.value = data.window.content_hash; canSignResponse.value = data.can_sign_clinical === true; } catch (failure) { if (current(ticket) && seq === candidateSequence) error.value = failure?.message || "AKI原来源目录未能核对"; } finally { if (current(ticket) && seq === candidateSequence) candidateLoading.value = false; } }
async function loadBaseline() { if (!allowed.value || inactive || creating.value || !canSign.value || !candidatesWindowHash.value) return; form.value.baselineId = ""; const ticket = capture(), seq = ++baselineSequence, originalAdmission = baselineAdmission.value || ticket.admissionId, originalPage = baselinePage.value; baselines.value = []; baselineLoading.value = true; error.value = ""; try { const res = await getAkiCandidates({ ...query(ticket), ...(baselineAdmission.value ? { baseline_admission_id: baselineAdmission.value } : {}), baseline_page: originalPage, baseline_page_size: 50 }); if (!current(ticket) || seq !== baselineSequence || originalAdmission !== (baselineAdmission.value || ticket.admissionId) || originalPage !== baselinePage.value) return; validateCandidates(res.data, ticket, originalAdmission); if (res.data.window.content_hash !== candidatesWindowHash.value || res.data.baseline_admission_id !== originalAdmission) throw new Error("原窗口或明确基线原住院已变化"); baselines.value = res.data.baseline_sources; baselineTotal.value = res.data.baseline_total; } catch (failure) { if (current(ticket) && seq === baselineSequence) error.value = failure?.message || "原住院基线目录未能核对"; } finally { if (current(ticket) && seq === baselineSequence) baselineLoading.value = false; } }
function requestMatches(actual, expected) { if (!actual || typeof actual !== "object") return false; const copy = { ...actual }; for (const key of ["evaluation_at", "rrt_started_at"]) { if (actual[key] === null || expected[key] === null) { if (actual[key] !== expected[key]) return false; } else { try { if (observationTime(actual[key]).microseconds !== observationTime(expected[key]).microseconds) return false; copy[key] = expected[key]; } catch { return false; } } } return akiCanonical(copy) === akiCanonical(expected); }
async function create() { if (!canCreate.value || inactive) return; const body = payload(), ticket = capture(); clearSelection(); creating.value = true; error.value = ""; try { const res = await createAkiAssessment(body); if (!current(ticket)) return; const row = res.data; if (!akiAssessmentMatches(row, ticket.patientId, ticket.admissionId, ticket.windowId) || row.window_content_hash !== body.expected_window_hash || row.rule_profile_id !== body.rule_profile_id || row.rule_profile_content_hash !== body.expected_rule_profile_hash || !requestMatches(row.snapshot?.attestation, body) || row.status !== "active" || row.revision !== 1) throw new Error("AKI登记回执与明确原资料或规则不一致"); form.value = blank(); page.value = 1; await loadSources(); if (current(ticket)) notice.value = "成人AKI来源已登记；请明确选择并核对，尚未调用规则服务或自动计算。"; } catch (failure) { if (current(ticket)) error.value = failure?.response?.data?.detail || failure?.message || "成人AKI来源登记失败"; } finally { if (current(ticket)) creating.value = false; } }
async function revoke() { if (!allowed.value || inactive || selected.value?.can_revoke !== true || !revokeReason.value.trim() || revoking.value) return; const ticket = capture(), original = selected.value, reason = revokeReason.value.trim(); clearSelection(); revoking.value = true; try { const res = await revokeAkiAssessment(original.assessment_id, { patient_id: ticket.patientId, admission_id: ticket.admissionId, expected_revision: original.revision, reason }); if (!current(ticket)) return; const row = res.data; if (!akiAssessmentMatches(row, ticket.patientId, ticket.admissionId, ticket.windowId) || row.assessment_id !== original.assessment_id || row.content_hash !== original.content_hash || row.status !== "revoked" || row.revision !== original.revision + 1) throw new Error("AKI撤销回执与原来源版本不一致"); await loadSources(); if (current(ticket)) notice.value = "成人AKI原评估已撤销；旧选择不能继续计算，请重新核实来源。"; } catch (failure) { if (current(ticket)) error.value = failure?.message || "成人AKI原来源撤销失败"; } finally { if (current(ticket)) revoking.value = false; } }
watch(selectedId, async id => { const ticket = capture(), seq = ++detailSequence; selected.value = null; emit("selection", null); emit("availability", false); error.value = ""; if (!id || !allowed.value || inactive) return; checking.value = true; try { const res = await getAkiAssessment(id, { patient_id: ticket.patientId, admission_id: ticket.admissionId }); if (!current(ticket) || seq !== detailSequence || selectedId.value !== id) return; const row = res.data; if (!akiAssessmentMatches(row, ticket.patientId, ticket.admissionId, ticket.windowId, true) || row.assessment_id !== id || row.status !== "active" || row.revision !== 1 || row.eligible !== true || row.freshness?.state !== "current") throw new Error("AKI原评估、窗口、规则或选定原资料已变化，不能作为当前计算来源"); selected.value = row; emit("selection", { aki_assessment_id: id, content_hash: row.content_hash }); emit("availability", true); } catch (failure) { if (current(ticket) && seq === detailSequence) error.value = failure?.message || "AKI原评估未能核对"; } finally { if (current(ticket) && seq === detailSequence) checking.value = false; } });
watch(() => [form.value.indexId, form.value.comparisonId, form.value.baselineId, form.value.evaluation_at], () => { form.value.serum_creatinine_confirmed = false; form.value.creatinine_review_note = ""; form.value.baseline_rise_within_7d_confirmed = false; form.value.baseline_review_note = ""; }, { flush: "sync" });
watch(() => form.value.rrt_status, () => { form.value.rrt_started_at = ""; form.value.rrt_acute_aki_confirmed = false; form.value.rrt_basis_note = ""; }, { flush: "sync" });
watch(() => form.value.weightId, () => { form.value.weight_applicability_confirmed = false; form.value.weight_basis_note = ""; }, { flush: "sync" });
watch(baselineAdmission, () => { baselineSequence++; baselines.value = []; baselinePage.value = 1; baselineTotal.value = null; form.value.baselineId = ""; baselineLoading.value = false; });
watch(scopeKey, () => { reset(); loadSources(); }, { immediate: true, flush: "sync" });
onDeactivated(() => { inactive = true; reset(); }); onActivated(() => { if (inactive) { inactive = false; reset(); loadSources(); } }); onBeforeUnmount(() => { inactive = true; reset(); });
</script>
